const SANDALWOOD_INFO={id:"sandalwood-carving",title:"Sandalwood Carving of Karnataka",originRegions:"Mysore, Srirangapatna, Bangalore — Karnataka, South India",history:"Sandalwood carving in Karnataka has a storied heritage of over 2,000 years, closely tied to the royal Wadiyar dynasty of Mysore.",materials:"Mysore Sandalwood (Santalum album), traditional chisels, gouges, rifflers, natural oils",giTag:"Mysore Sandalwood Oil & Agarbathi — GI Tagged",quickStats:[{label:"Origin",value:"Karnataka",icon:"📍"},{label:"Wood",value:"Santalum album",icon:"🪵"},{label:"GI Tag",value:"Protected Craft",icon:"🏷️"},{label:"Heritage",value:"2,000+ Years",icon:"⏳"},{label:"Artisan Hubs",value:"Mysore & Bangalore",icon:"🏛️"},{label:"World Fame",value:"Export Quality",icon:"🌏"}]},TIMELINE_EVENTS=[{year:"~2nd Century BCE",title:"Ancient Origins",description:"Sandalwood trade routes from South India to Arabia and Rome are documented. The fragrant wood from the Western Ghats was prized for carving sacred objects, incense, and medicinal use."},{year:"14th–16th Century",title:"Vijayanagara Patronage",description:"The Vijayanagara Empire elevated sandalwood carving to a royal art form. Temples commissioned large deity idols, panels, and ceremonial chariots (rathas) from master carvers (shilpis)."},{year:"17th–19th Century",title:"Mysore Royal Court",description:"The Wadiyar dynasty of Mysore made Mysore Sandalwood globally famous. Royal ateliers employed hundreds of hereditary carvers whose work adorned palace doors, thrones, and ceremonial gifts sent to foreign dignitaries."},{year:"1916",title:"Government Sandalwood Depot",description:"The Mysore State Government established the Karnataka Soaps & Detergents Ltd. and regulated sandalwood cultivation. State patronage ensured carvers had access to quality wood and market connections."},{year:"1970s–Present",title:"GI Protection & Revival",description:"Geographical Indication (GI) tags now protect Mysore sandalwood products. Government craft schools in Mysore train new generations, while the craft finds global export markets through e-commerce platforms."}],CARVING_TECHNIQUES=[{step:1,title:"Wood Selection & Seasoning",description:"Only mature Santalum album trees (25–30 years old) are harvested. The heartwood — dense, aromatic, and creamy-yellow in color — is selected by master carvers. The wood is seasoned for months to reduce moisture, preventing cracks.",icon:"🪵"},{step:2,title:"Sketching & Marking",description:"The carver traces the design onto the wood block with fine pencil lines. Traditional designs are passed down through family lineages or drawn from illustrated shilpa-shastra manuscripts governing temple iconography.",icon:"✏️"},{step:3,title:"Rough Shaping (Boching)",description:"Large chisels and mallets remove excess material to establish the primary silhouette. This stage demands physical strength and a trained eye — a wrong cut here cannot be corrected without replacing the block entirely.",icon:"🔨"},{step:4,title:"Detailed Carving (Filigree Work)",description:"Fine-tipped gouges, rifflers, and burins are used to carve intricate details — petal patterns, fabric folds, facial expressions, and lace-like filigree. This stage can take weeks or months for a single piece.",icon:"🪡"},{step:5,title:"Sanding & Polishing",description:"Progressive grits of sandpaper smooth the carved surface. The natural aromatic oils of sandalwood are drawn out during polishing, producing a lustrous, glowing finish without requiring additional varnish.",icon:"✨"},{step:6,title:"Preservation & Finishing",description:"A final coat of sandalwood oil or beeswax polish protects the surface and enhances the warm amber color. Pieces are wrapped in muslin cloth for storage, allowing the wood to breathe and retain fragrance for decades.",icon:"🛡️"}],TRADITIONAL_MOTIFS=[{name:"Lotus (Padma)",symbol:"🪷",description:"The sacred lotus — emblem of purity, prosperity, and Lakshmi — appears as a recurring base, surrounding border, or full standalone motif in sandalwood panels and deity sculptures.",significance:"Sacred & Auspicious"},{name:"Elephant (Gaja)",symbol:"🐘",description:"The royal elephant is both the most iconic Karnataka motif and one of the most technically demanding. Carvers must articulate tusk, toenail, and caparison detail at micro-scale.",significance:"Royalty & Strength"},{name:"Peacock (Mayura)",symbol:"🦚",description:"Karnataka's state bird appears prominently in decorative panels, jewelry boxes, and screens. The fanned tail with its hundreds of \"eyes\" is a showcase of a carver's filigree skill.",significance:"Beauty & Grace"},{name:"Divine Deities",symbol:"🙏",description:"Ganesha, Lakshmi, Krishna, Saraswati, and the Dashavatara of Vishnu are carved in strict proportions per Agama-shastra guidelines. These command the highest craft skill and ritual reverence.",significance:"Devotional Art"},{name:"Temple Gopuram",symbol:"🛕",description:"Miniature architectural facades — complete with towers, pillars, and relief figures — are recreated in sandalwood, preserving the Hoysala and Dravidian architectural vocabulary in portable form.",significance:"Architectural Heritage"},{name:"Creeper Scroll (Lata)",symbol:"🌿",description:"Flowing vine-and-flower scrollwork (lata-pattern) borders almost every piece, framing the central motif. The unbroken flow of the vine symbolizes eternity and continuous creation.",significance:"Eternity & Life"}],GALLERY_ITEMS=[{title:"Royal Elephant Sculpture",caption:"A ceremonial elephant in full caparison — one of Mysore's most iconic carving traditions. Each piece takes 3–6 months to complete.",image:"assets/sandalwood_elephant.jpg",tag:"🐘 Signature Piece"},{title:"Sacred Ganesha Idol",caption:"A devotional Ganesha carved per Agama-shastra proportions. These are among the most gifted pieces at Karnataka weddings and auspicious occasions.",image:"assets/sandalwood_deity.jpg",tag:"🙏 Devotional"},{title:"Ornate Jewelry Box",caption:"A Mysore-style sandalwood jewelry box with peacock lid carving and floral border panels — a globally sought-after luxury craft item.",image:"assets/sandalwood_box.jpg",tag:"✨ Decorative"},{title:"The Artisan's Hand",caption:"A master shilpi at work in a Mysore workshop — demonstrating the generational skill transfer that has kept this 2,000-year-old craft alive.",image:"assets/sandalwood_artisan.jpg",tag:"🤝 Living Heritage"}],ARTISAN_CENTERS=[{city:"Mysore",icon:"🏛️",description:"The cultural heart of Karnataka's sandalwood carving. The Mysore Government Central Market, Devaraja Market, and Karnataka Emporium are the main hubs where master carvers sell directly.",highlight:"Primary Hub"},{city:"Srirangapatna",icon:"🏰",description:"The former capital of Tipu Sultan houses generations of hereditary carving families. This historic town is known for fine filigree deity carvings and miniature temple models.",highlight:"Heritage Workshop Town"},{city:"Bangalore",icon:"🏙️",description:"The Karnataka Chitrakala Parishath and Government craft emporiums in Bangalore serve as modern market and training centers, connecting artisans to national and international buyers.",highlight:"Market & Export Hub"},{city:"Shimoga",icon:"🌲",description:"Located closer to the sandalwood-growing districts, Shimoga artisans specialize in larger architectural pieces and are known for raw-finish sculptural work.",highlight:"Sculptural Tradition"}],PRESERVATION_FACTS=[{title:"GI Tag Protection",description:"Mysore Sandal Oil, Soap, and associated craft products carry Geographical Indication (GI) status, legally protecting the brand and ensuring that only Karnataka-origin sandalwood products use the name.",icon:"🏷️"},{title:"KSRTC Craft Schools",description:"The Karnataka government runs dedicated craft training schools in Mysore and Bangalore, where students from carving families receive formal training alongside market development support.",icon:"🎓"},{title:"Dasara Festival Platform",description:"The annual Mysore Dasara (Navaratri) festival — one of India's most spectacular — serves as the premier showcase for sandalwood carvers, attracting global collectors and press each year.",icon:"🎪"},{title:"Online & Export Markets",description:"Karnataka handicraft boards have partnered with e-commerce platforms and export houses, allowing artisans to directly reach buyers in the USA, Japan, Germany, and the Gulf countries.",icon:"🌐"}],REFERENCES=[{text:"Karnataka Handicrafts Development Corporation — Sandalwood Carving",link:"https://www.karnatakahandicraft.gov.in/"},{text:"Office of the Development Commissioner for Handicrafts, Ministry of Textiles, Govt. of India",link:"https://handicrafts.nic.in/"},{text:"Geographical Indications Registry — Mysore Sandal Soap & Products",link:"https://ipindia.gov.in/gi-public-search.htm"},{text:"Karnataka Soaps & Detergents Ltd. — Mysore Sandal Heritage",link:"https://www.karnatakasoap.com/"},{text:"UNESCO Intangible Cultural Heritage — Traditional Craftsmanship of South India",link:"https://ich.unesco.org/"}];"undefined"!=typeof module&&module.exports&&(module.exports={SANDALWOOD_INFO:SANDALWOOD_INFO,TIMELINE_EVENTS:TIMELINE_EVENTS,CARVING_TECHNIQUES:CARVING_TECHNIQUES,TRADITIONAL_MOTIFS:TRADITIONAL_MOTIFS,GALLERY_ITEMS:GALLERY_ITEMS,ARTISAN_CENTERS:ARTISAN_CENTERS,PRESERVATION_FACTS:PRESERVATION_FACTS,REFERENCES:REFERENCES});